def maximumProfit(n, present, future, hierarchy, budget):
    NEG = float('-inf')
    tree = [[] for _ in range(n)]
    for u, v in hierarchy:
        tree[u - 1].append(v - 1)  # u is the direct boss of v (0-indexed)

    def merge(a, b):
        # knapsack-style combination of two "exact spend" arrays
        res = [NEG] * (budget + 1)
        for i in range(budget + 1):
            if a[i] == NEG:
                continue
            for j in range(budget + 1 - i):
                if b[j] != NEG and a[i] + b[j] > res[i + j]:
                    res[i + j] = a[i] + b[j]
        return res

    def dfs(u):
        # returns (f0, f1): f0[b] / f1[b] = max profit in u's subtree spending exactly b,
        # when u's boss did not buy (f0) / did buy (f1)
        no_buy = [NEG] * (budget + 1)   # u does not buy: children see "boss did not buy"
        no_buy[0] = 0
        bought = [NEG] * (budget + 1)   # u buys: children see "boss bought"
        bought[0] = 0
        for child in tree[u]:
            c0, c1 = dfs(child)
            no_buy = merge(no_buy, c0)
            bought = merge(bought, c1)

        f0 = no_buy[:]
        f1 = no_buy[:]
        # u buys at full price (boss did not buy)
        price = present[u]
        for b in range(price, budget + 1):
            if bought[b - price] != NEG:
                f0[b] = max(f0[b], bought[b - price] + future[u] - price)
        # u buys at half price (boss bought)
        price = present[u] // 2
        for b in range(price, budget + 1):
            if bought[b - price] != NEG:
                f1[b] = max(f1[b], bought[b - price] + future[u] - price)
        return f0, f1

    f0, _ = dfs(0)   # the CEO has no boss, so no discount
    return max(f0)
